import { useMemo, useState } from 'react';

type UserStatus = 'active' | 'disabled';

interface User {
  id: string | number;
  name: string;
  role: string;
  status: UserStatus;
}

interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

const STATUS_LABEL: Record<UserStatus, string> = {
  active: 'Активен',
  disabled: 'Отключён',
};

const STATUS_TOKEN: Record<UserStatus, string> = {
  active: 'var(--jx-color-success)',
  disabled: 'var(--jx-color-danger)',
};

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const totalPages = Math.max(1, Math.ceil(users.length / PAGE_SIZE));
  const safePage = Math.min(page, totalPages);

  const pageUsers = useMemo(() => {
    const start = (safePage - 1) * PAGE_SIZE;
    return users.slice(start, start + PAGE_SIZE);
  }, [users, safePage]);

  return (
    <div className="jx-stack" style={{ gap: 'var(--jx-space-md)' }}>
      <table className="jx-table" style={{ width: '100%' }}>
        <thead>
          <tr>
            <th className="jx-table__head-cell">Имя</th>
            <th className="jx-table__head-cell">Роль</th>
            <th className="jx-table__head-cell">Статус</th>
          </tr>
        </thead>
        <tbody>
          {pageUsers.map((user) => (
            <tr key={user.id} className="jx-table__row">
              <td className="jx-table__cell">{user.name}</td>
              <td className="jx-table__cell">{user.role}</td>
              <td className="jx-table__cell">
                <span
                  className="jx-badge"
                  style={{ color: STATUS_TOKEN[user.status] }}
                >
                  {STATUS_LABEL[user.status]}
                </span>
              </td>
            </tr>
          ))}
          {pageUsers.length === 0 && (
            <tr>
              <td className="jx-table__cell" colSpan={3}>
                Нет пользователей
              </td>
            </tr>
          )}
        </tbody>
      </table>

      <nav
        className="jx-pagination"
        aria-label="Постраничная навигация"
        style={{ display: 'flex', gap: 'var(--jx-space-sm)', alignItems: 'center' }}
      >
        <button
          type="button"
          className="jx-button jx-button--secondary"
          disabled={safePage <= 1}
          onClick={() => setPage((p) => Math.max(1, p - 1))}
        >
          Назад
        </button>
        <span>
          Страница {safePage} из {totalPages}
        </span>
        <button
          type="button"
          className="jx-button jx-button--secondary"
          disabled={safePage >= totalPages}
          onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
        >
          Вперёд
        </button>
      </nav>
    </div>
  );
}

